using System; using System.Collections; using UnityEngine; using UnityEngine.UI;
namespace Reflectable { [RequireComponent(typeof(BoxCollider2D))] public sealed class BlockController:MonoBehaviour { public int MaxHP{get;private set;} public int CurrentHP{get;private set;} public int GridRow{get;private set;} public int GridColumn{get;private set;} public BlockType Type{get;private set;} public event Action<BlockController,int> Hit; public event Action<BlockController> Destroyed; Transform visual; Text hp; public void Setup(int row,int col,int max,BlockType type,Text label){GridRow=row;GridColumn=col;MaxHP=CurrentHP=max;Type=type;hp=label;visual=transform; Refresh();} public void Damage(int amount){if(CurrentHP<=0)return;CurrentHP=Mathf.Max(0,CurrentHP-amount);Refresh();Hit?.Invoke(this,amount);StartCoroutine(Punch());if(CurrentHP==0)Destroyed?.Invoke(this);} void Refresh(){if(hp)hp.text=(Type==BlockType.Bomb?"✦\n":Type==BlockType.Gem?"◆\n":"")+CurrentHP;} IEnumerator Punch(){visual.localScale=new Vector3(1.52f,1.15f,1);yield return new WaitForSeconds(.08f);if(visual)visual.localScale=Vector3.one*1.35f;} public void SetGridRow(int row){GridRow=row;} } }
